<template><section class="graph-overview"><div class="go-heading"><strong>图谱数据总览</strong><span>文件存储 · 两套数据分别检索，不自动认定事件因果</span></div><div class="go-sources"><div><span>附件客户销量数据</span><p><b>{{nodes.length.toLocaleString()}}</b> 节点 <b>{{edgeCount.toLocaleString()}}</b> 关系</p><small>2025年1—11月 · 原始 CSV 已完整导入</small></div><div><span>事件传导示例</span><p><b>{{eventNodes}}</b> 节点 <b>{{eventEdges}}</b> 关系</p><small>PPT部分场景与业务示例 · 不包含在附件节点数量内</small></div></div><div class="go-types"><span v-for="row in types" :key="row.name">{{row.name}} <b>{{row.count.toLocaleString()}}</b></span></div><p v-if="error">{{error}}</p></section></template>
<script setup>
import {ref,computed,onMounted} from 'vue'
const nodes=ref([]),edgeCount=ref(0),eventNodes=ref(0),eventEdges=ref(0),error=ref('')
const types=computed(()=>{const counts=new Map();for(const n of nodes.value)counts.set(n.type,(counts.get(n.type)||0)+1);return [...counts].map(([name,count])=>({name,count})).sort((a,b)=>b.count-a.count)})
onMounted(async()=>{try{const [a,b]=await Promise.all([fetch('/customer-graph.json'),fetch('/reasoning-graph.json')]);if(!a.ok||!b.ok)throw Error();const [customer,event]=await Promise.all([a.json(),b.json()]);nodes.value=customer.nodes;edgeCount.value=customer.edges.length;eventNodes.value=event.nodes.length;eventEdges.value=event.edges.length}catch{error.value='数据总览加载失败，请刷新重试'}})
</script>
<style scoped>
.graph-overview{border:1px solid var(--wb-ui-border);background:var(--wb-ui-surface);border-radius:12px;padding:18px 20px;margin:20px 0}.go-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.go-heading strong{color:var(--wb-ui-text);font-size:var(--wb-font-body)}.go-heading>span{font-size:var(--wb-font-meta);color:var(--wb-ui-text)}.go-sources{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:16px 0}.go-sources>div+div{border-left:1px solid var(--wb-ui-border);padding-left:24px}.go-sources span{font-size:var(--wb-font-meta);color:var(--wb-ui-secondary)}.go-sources p{font-size:var(--wb-font-meta);color:var(--wb-ui-secondary);margin:9px 0}.go-sources b{font-size:23px;color:var(--wb-ui-text);margin-right:6px}.go-sources b:not(:first-child){margin-left:18px}.go-sources small{font-size:var(--wb-font-meta);color:var(--wb-ui-secondary)}.go-types{display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--wb-ui-border);padding-top:13px}.go-types span{font-size:var(--wb-font-meta);color:var(--wb-ui-secondary);background:var(--wb-ui-surface-raised);border:1px solid var(--wb-ui-border);border-radius:5px;padding:5px 8px}.go-types b{color:var(--wb-ui-text);margin-left:5px}@media(max-width:800px){.go-heading{display:block}.go-heading>span{display:block;margin-top:8px}.go-sources{grid-template-columns:1fr}.go-sources>div+div{border-left:0;padding-left:0}}
</style>
